def count_nums(arr):
    count = 0
    for n in arr:
        if n == 0:
            continue
        s = str(n)
        if s[0] == '-':
            total = -int(s[1])
            for c in s[2:]:
                total += int(c)
        else:
            total = sum(int(c) for c in s)
        if total > 0:
            count += 1
    return count
